/// <summary>
/// Gets the main (blanket) sales order ID linked to the current sales order.
/// </summary>
/// <returns>
/// The <c>SalesIdBlanket</c> value representing the main sales order ID.
/// </returns>
display SalesIdBlanket salesIdBlanket()
{
    return SalesTableLinks::find(this.SalesId).MainSalesId;
}
